','%s option reset'=>'Pengaturan ulang opsi %s','Please specify if you would like to disconnect a blog or user.'=>'Silakan tentukan apakah Anda hendak memutuskan sambungan sebuah blog atau seorang pengguna.','User has been successfully disconnected.'=>'Pengguna berhasil diputus sambungannya.','Jetpack has been successfully disconnected for %s.'=>'Jetpack berhasil diputus sambungannya dari %s.','Please specify a user by either ID, username, or email.'=>'Harap tentukan pengguna baik berdasarkan ID, nama pengguna, atau email.','Please specify a valid user.'=>'Silakan tentukan seorang pengguna yang sah.','"wp jetpack status full" is a command - do not translateView full status with \'wp jetpack status full\''=>'Tampilkan status penuh dengan \'wp jetpack status full\'','Additional data: '=>'Data tambahan: ','The WordPress.com blog_id is %d'=>'blog_id WordPress.com ialah %d','The Jetpack Version is %s'=>'Versi Jetpack ialah %s','Jetpack is currently connected to WordPress.com'=>'Jetpack telah tersambung dengan WordPress.com','%s is not a valid command.'=>'%s bukanlah perintah yang sah.','Jetpack is not currently connected to WordPress.com'=>'Jetpack belum tersambung dengan WordPress.com','Configure'=>'Konfigurasikan','Popular'=>'Populer','Newest'=>'Terbaru','Inactive'=>'Tidak aktif','Active'=>'Aktif','All'=>'Semua','Search'=>'Cari','Jetpack Settings'=>'Pengaturan Jetpack','My Jetpack'=>'Jetpack Saya','Feedback'=>'Feedback','Settings'=>'Pengaturan','Jetpack'=>'Jetpack','Learn More'=>'Pelajari Lebih Lanjut','Debug'=>'Debug','Privacy'=>'Privasi']];